"""Current citywide factor figures and a small source-layer viewer."""
from pathlib import Path
import json,gzip,base64,shutil
import geopandas as gpd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'output/plano_city/accessibility';DEST=ROOT/'netlify_site/src'

def run():
 b=gpd.read_file(OUT/'block_accessibility.gpkg');city=gpd.read_file(ROOT/'data/processed/plano_reference/plano_city_boundary.gpkg').to_crs(b.crs)
 rows=[{'image':'block_accessibility_all_categories.png','title':'Plano city accessibility — nearest POI per category','caption':'Average minimum weighted trip cost to one candidate in each service category. Equal category weights. Blue lower, red higher. Gray incomplete; block entrances unverified.'},{'image':'block_accessibility_essential.png','title':'Plano city accessibility — temple, grocery and pharmacy','caption':'Average lowest-friction trip to a Hindu temple candidate, supermarket and pharmacy. Candidate catalog is incomplete; housing/entrance suitability unverified.'},{'image':'plano_weighted_network.png','title':'Plano city weighted walking network','caption':'Actual OSM walking network with block-context friction weights. Blue/red colors stretch city 2nd–98th percentiles; actual route weights are unchanged. A 1 km routing buffer is included.'}]
 factors=[('ai_canopy_cover_pct','plano_ai_tree_cover.png','GeoAI-predicted tree cover · Plano','YlGn','Predicted tree cover (%)'),('landsat_summer_surface_temp_c','plano_surface_temperature.png','Summer 2025 surface temperature · Plano','YlOrRd','Surface temperature (°C)'),('traffic_index_0_100','plano_traffic_burden.png','Nearby mapped traffic volume · Plano','Blues','City-referenced traffic index (0–100)')]
 for field,image,title,cmap,label in factors:
  fig,ax=plt.subplots(figsize=(12,8));b.plot(ax=ax,column=field,cmap=cmap,linewidth=0,legend=True,legend_kwds={'label':label,'shrink':.7},missing_kwds={'color':'#adb5bd'});city.boundary.plot(ax=ax,color='#333',linewidth=.8);ax.set_title(title);ax.set_axis_off()
  caption='Pretrained Restor TCD model applied to 2022 NAIP, including new city inference and reused compatible pilot predictions.\nTree cover is not measured shade; local segmentation accuracy unvalidated.' if field=='ai_canopy_cover_pct' else 'Clear-sky June–August 2025 Landsat surface-temperature medians around noon; not air temperature or daily peak.\nNative thermal information about 100 m, delivered at 30 m. Gray blocks have no direct block summary.' if field.startswith('landsat') else '100 m buffered block context from mapped TxDOT AADT. Existing City-of-Plano log/CDF normalization.\nHigher index means more nearby mapped traffic; not crash risk or pedestrian exposure measurement.'
  fig.text(.05,.025,caption,fontsize=9);fig.tight_layout(rect=[0,.07,1,1]);fig.savefig(OUT/image,dpi=180);plt.close(fig);rows.append({'image':image,'title':title,'caption':caption.replace('\n',' ')})
 (OUT/'figure_captions.json').write_text(json.dumps(rows,indent=2))
 keep=['GEOID20','ai_canopy_cover_pct','landsat_summer_surface_temp_c','traffic_index_0_100','ai_imagery_coverage_01','geometry'];data=json.loads(b[keep].to_crs(4326).to_json(drop_id=True));encoded=base64.b64encode(gzip.compress(json.dumps(data,separators=(',',':')).encode())).decode()
 html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Plano environmental inputs</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>html,body,#map{height:100%;margin:0;font:14px system-ui}.card{background:white;padding:12px;max-width:330px;border-radius:6px;box-shadow:0 1px 5px #999}select{padding:8px}</style><div id="map"></div><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const map=L.map('map',{preferCanvas:true});L.tileLayer('https://empathmaps.netlify.app/.netlify/functions/basemap?z={z}&x={x}&y={y}',{attribution:'© OpenStreetMap contributors · © CARTO',maxZoom:20}).addTo(map);let field='ai_canopy_cover_pct';const settings={ai_canopy_cover_pct:{title:'AI tree cover (%)',min:0,max:100,colors:['#ffffcc','#006837']},traffic_index_0_100:{title:'Traffic index (0–100)',min:0,max:100,colors:['#eff3ff','#08519c']},landsat_summer_surface_temp_c:{title:'Surface temperature (°C)',min:__LO__,max:__HI__,colors:['#ffffcc','#800026']}};
function color(v){if(v==null)return '#adb5bd';const s=settings[field],t=Math.max(0,Math.min(1,(v-s.min)/(s.max-s.min)));const c=s.colors.map(x=>[1,3,5].map(i=>parseInt(x.slice(i,i+2),16)));return '#'+c[0].map((x,i)=>Math.round(x+(c[1][i]-x)*t).toString(16).padStart(2,'0')).join('');}
(async()=>{const bytes=Uint8Array.from(atob('__DATA__'),c=>c.charCodeAt(0));const data=JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());const style=f=>({color:'#666',weight:.3,fillColor:color(f.properties[field]),fillOpacity:.8});const layer=L.geoJSON(data,{style,onEachFeature:(f,l)=>l.bindPopup(()=>'<b>Block '+f.properties.GEOID20+'</b><br>'+settings[field].title+': '+(f.properties[field]==null?'Unknown':f.properties[field].toFixed(2))+'<br>Source block summary, not a direct sidewalk measurement.')}).addTo(map);map.fitBounds(layer.getBounds());const control=L.control({position:'topright'});control.onAdd=()=>{const d=L.DomUtil.create('div','card');d.innerHTML='<b>Plano city · environmental inputs</b><br><select id="factor"><option value="ai_canopy_cover_pct">GeoAI tree cover</option><option value="traffic_index_0_100">Mapped traffic volume</option><option value="landsat_summer_surface_temp_c">Landsat surface temperature</option></select><p id="range"></p><small>Gray = source summary missing.<br>Tree cover is not actual shade.<br>Surface temperature is not air temperature.<br>Traffic index is not collision risk.</small>';L.DomEvent.disableClickPropagation(d);return d;};control.addTo(map);function update(){field=document.getElementById('factor').value;layer.setStyle(style);const s=settings[field];document.getElementById('range').textContent=s.title+': '+s.min.toFixed(1)+'–'+s.max.toFixed(1);}document.getElementById('factor').onchange=update;update();})();</script>'''
 html=html.replace('__DATA__',encoded).replace('__LO__',str(float(b.landsat_summer_surface_temp_c.min()))).replace('__HI__',str(float(b.landsat_summer_surface_temp_c.max())))
 (OUT/'plano_environment.html').write_text(html);(DEST/'maps/plano_environment.html').write_text(html)
 for row in rows:shutil.copy2(OUT/row['image'],DEST/'figures'/row['image'])
 return rows
if __name__=='__main__':run()
